INSERT INTO `about_us` (`id`, `eyebrow`, `banner_image`, `main_image`, `heading`, `description`, `badge1_text`, `badge1_icon`, `badge2_text`, `badge2_icon`, `badge3_text`, `badge3_icon`, `products_count`, `customers_count`, `success_percentage`, `action_text`, `action_button_text`, `action_button_link`, `created_at`, `updated_at`, `purpose_eyebrow`, `purpose_heading`, `p1_icon`, `p1_title`, `p1_text`, `p2_icon`, `p2_title`, `p2_text`, `p3_icon`, `p3_title`, `p3_text`, `p4_icon`, `p4_title`, `p4_text`) VALUES
(1, 'Est. 2016 · Sivakasi', 'uploads/about/1772873887_banner_ab.jpg', 'uploads/about/1772873170_main_about.jpg', 'About<br>The Crackers', 'Located in the heart of <strong>Sivakasi</strong>, <strong>The Crackers</strong> has been a symbol of festivity since <strong>2016</strong>. Renowned for providing top-notch fireworks that light up the sky with dazzling colours and joy, we are the go-to choice for all celebrations.<br><br>Our dedication to <strong>quality, affordability, variety, timely delivery, and safety</strong> has established us as the preferred destination for your celebratory needs. Our reputation as a reliable brand has been solidified by our commitment to quality, safety, and a large selection of pyrotechnics.<br><br>For a memorable celebration — be it a lavish festival, a happy occasion, or an intimate gathering — <strong>The Crackers</strong> has the perfect fireworks to make it <strong>unforgettable</strong>.', 'Since 2016', '🏆', 'Sivakasi Based', '🔥', 'Safety Certified', '🛡️', 250, 1200, 100, 'Let\'s Make a Difference in the Lives of Others', 'ESTIMATE NOW', '/estimate', '2026-03-03 04:59:35', '2026-03-08 22:44:57', 'What Drives Us', 'Our Purpose & Values', 'fa-solid fa-bullseye', 'Our Purpose', 'To illuminate your happy and festive times while establishing new benchmarks for outstanding cracker experiences. Every burst of light we deliver carries our commitment to making your moments truly spectacular and safe.', 'fa-solid fa-heart-pulse', 'Our Dedication', 'Providing a wide variety of crackers — from eye-catching sparklers to spectacular aerial shells — so that every party is as colourful and distinctive as you are. Quality and joy, guaranteed with every order.', 'fa-solid fa-award', 'Our Quality', 'Every cracker is sourced directly from certified Sivakasi manufacturers and meets government safety standards. We never compromise on quality — because your family\'s safety and smiles are our highest priority.', 'fa-solid fa-handshake', 'Our Promise', 'Thousands of happy customers trust The Crackers year after year for Diwali and every festival. We promise competitive prices, eco-friendly solutions, and an experience that keeps you coming back every celebration season.');
