INSERT INTO `home_settings` (`id`, `hero_eyebrow`, `welcome_heading`, `welcome_text`, `badge1_text`, `badge2_text`, `badge3_text`, `welcome_image`, `welcome_button_text`, `welcome_button_link`, `created_at`, `updated_at`, `products_eyebrow`, `products_heading`, `featured_product_ids`, `why_heading_data`, `why_pillars`, `why_dials`, `why_stats`) VALUES
(1, 'Est. 2026 · Sivakasi', 'Welcome to<br>The Crackers!', 'Since 2026, <strong>The Crackers</strong> has been the <strong>No.1 destination</strong> for all your celebration needs. Located in <strong>Sivakasi</strong>, the heart of India\'s fireworks industry, we are renowned for offering an impressive range of crackers that add magic to every occasion.<br><br>Whether you\'re planning for a grand festival, a joyous event, or an intimate gathering, The Crackers has the perfect fireworks to make it <strong>unforgettable</strong>. Our vast selection, competitive prices, and commitment to safety ensure your festivities are nothing short of extraordinary.', 'No.1 in Sivakasi', '80% Off Sale', 'Free Shipping ₹500+', 'uploads/home/1772869756_welcome_about.png', 'Read More', '/about', '2026-03-03 05:55:12', '2026-03-07 07:29:38', 'Handpicked Selection', 'Our Products', '[\"324\",\"213\",\"309\",\"310\",\"320\",\"332\",\"334\"]', '{\"eyebrow\":\"Our Promise\",\"title\":\"Why Choose Us\",\"subtitle\":\"Built on quality...\"}', '[{\"title\":\"Best Quality\",\"desc\":\"Every cracker is sourced directly...\"},{\"title\":\"Wide Variety\",\"desc\":\"From sparklers to aerial shells...\"},{\"title\":\"Safety First\",\"desc\":\"All products meet government...\"},{\"title\":\"Trusted Brand\",\"desc\":\"Thousands of happy customers...\"}]', '[{\"name\":\"Affordable Price\",\"pct\":\"97\"},{\"name\":\"Quick Delivery\",\"pct\":\"95\"},{\"name\":\"Easy Ordering\",\"pct\":\"99\"},{\"name\":\"Customer Support\",\"pct\":\"98\"}]', '[{\"number\":\"5000+\",\"label\":\"Happy Customers\"},{\"number\":\"200+\",\"label\":\"Products\"},{\"number\":\"80%\",\"label\":\"Max Discount\"},{\"number\":\"Pan India\",\"label\":\"Delivery\"}]');
